    "freq": "Campaign",
    "time": "days",
    "today": "Moving a jack-up between wells needs a certified, unbreached 48 to 72-hour weather window covering pull-out, tow, approach and pin-down, and a tug of sufficient bollard pull free in the same window. A basin with 35 rigs and 12 to 16 high-bollard-pull AHTS vessels is mathematically over-constrained, so the schedule is negotiated across four departments over 8 to 12 days of phone calls against a coarse global forecast that is already four to six hours stale.",
    "vuln": "The schedule is built on a forecast nobody can defend and a vessel pool nobody holds a complete view of, so it fails in two directions. It fails safe too often — rigs sit on standby waiting for a window that a better forecast would have shown was already open, and CAG Report No. 12 of 2021 records jack-ups delayed up to 26 days per move in the pre-monsoon season. It also fails unsafe: one unforecast swell event during spudcan extraction or pin-down, and a single vessel breakdown cascades cancellations across the whole basin.",
    "plug": "Solves the basin's rig relocation schedule as one constrained problem rather than thirty-five separate phone negotiations — matching each move to a forecast marine weather window that satisfies the operational sea-state limits end to end, against the tugs actually available in that window — and compiles the evidence dossier the Marine Warranty Surveyor needs to approve it.",
